import * as THREE from 'three';
import {walkStep,roomStation} from './interior-data.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountWalkthrough(bridge){
 const scene=bridge.getScene();let active=false,position=[0,1.6,0],yaw=0,pitch=0,last=0,drag=null,roomId=null,oldDown,decorations;
 const keys=new Set(),camera=new THREE.PerspectiveCamera(75,1,.05,1000);
 const hud=document.createElement('div');hud.className='walk-hud';hud.hidden=true;
 hud.innerHTML='<div class="walk-location"><span class="walk-live">LIVE 3D</span><strong id="walk-room-name"></strong><button id="walk-exit" class="button subtle">Exit walkthrough</button></div><div class="walk-navigation"><button aria-label="Turn left" data-walk-turn="-1">↶</button><button aria-label="Walk forward" data-walk-step="1">↑</button><button aria-label="Walk backward" data-walk-step="-1">↓</button><button aria-label="Turn right" data-walk-turn="1">↷</button></div><p>Drag to look · WASD / arrows to move · Q/E turn · Esc exit</p><svg id="walk-map" aria-label="Floor navigation map" role="img"></svg>';
 document.querySelector('.canvas-area').append(hud);
 document.querySelector('#walk-exit').onclick=stop;
 for(const b of hud.querySelectorAll('[data-walk-turn]'))b.onclick=()=>{yaw-=Number(b.dataset.walkTurn)*Math.PI/8;updateCamera();};
 for(const b of hud.querySelectorAll('[data-walk-step]'))b.onclick=()=>move(Number(b.dataset.walkStep)*.45,0);
 function map(){const floor=bridge.getFloor(),svg=hud.querySelector('svg'),rooms=floor.rooms;
   if(!rooms.length){svg.innerHTML='';return;}const x=Math.min(...rooms.map(r=>r.x)),z=Math.min(...rooms.map(r=>r.z)),w=Math.max(...rooms.map(r=>r.x+r.w))-x,d=Math.max(...rooms.map(r=>r.z+r.d))-z;
   svg.setAttribute('viewBox',`${x-.5} ${z-.5} ${w+1} ${d+1}`);
   svg.innerHTML=rooms.map(r=>`<g data-walk-room="${esc(r.id)}" role="button" tabindex="0" aria-label="Go to ${esc(r.name)}"><rect x="${r.x}" y="${r.z}" width="${r.w}" height="${r.d}" fill="${r.id===roomId?'#75618e':'#393942'}" stroke="#b9aec5" stroke-width=".05"/><title>${esc(r.name)}</title></g>`).join('')+`<circle cx="${position[0]}" cy="${position[2]}" r=".18" fill="#e5ccff"/><path d="M0 -.6L-.18 -.28H.18Z" transform="translate(${position[0]} ${position[2]}) rotate(${yaw*180/Math.PI})" fill="#e5ccff"/>`;
   for(const g of svg.querySelectorAll('[data-walk-room]')){g.onclick=()=>jump(g.dataset.walkRoom);g.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();jump(g.dataset.walkRoom);}};}
 }
 function updateCamera(){camera.position.fromArray(position);camera.rotation.set(pitch,yaw,0,'YXZ');const r=scene.canvas.getBoundingClientRect();camera.aspect=r.width/Math.max(1,r.height);camera.updateProjectionMatrix();
   const floor=bridge.getFloor(),room=floor.rooms.find(r=>position[0]>=r.x&&position[0]<=r.x+r.w&&position[2]>=r.z&&position[2]<=r.z+r.d);roomId=room?.id||roomId;hud.querySelector('strong').textContent=room?.name||'Floor walkthrough';map();
 }
 function move(forward,side){position=walkStep(bridge.getFloor(),position,Math.sin(yaw)*-forward+Math.cos(yaw)*side,Math.cos(yaw)*-forward-Math.sin(yaw)*side);updateCamera();}
 function jump(id,angle=0){const room=bridge.getFloor().rooms.find(r=>r.id===id);if(!room)throw Error('This room is not on the current floor.');const spot=roomStation(bridge.getFloor(),room);if(!spot)throw Error('This room has no clear walking point.');if(!active)start(id);position=spot;yaw=angle;pitch=0;roomId=id;updateCamera();bridge.onWalkChange?.();}
 function ceiling(){decorations?.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});decorations?.removeFromParent();decorations=new THREE.Group();decorations.name='Walkthrough ceilings';const floor=bridge.getFloor(),height=Math.max(2.4,...floor.walls.map(w=>w.height));for(const r of floor.rooms){const mesh=new THREE.Mesh(new THREE.PlaneGeometry(r.w,r.d),new THREE.MeshStandardMaterial({color:'#eeeae3',roughness:1,side:THREE.DoubleSide}));mesh.rotation.x=Math.PI/2;mesh.position.set(r.x+r.w/2,height,r.z+r.d/2);decorations.add(mesh);}scene.scene.add(decorations);}
 function start(id){if(!scene)throw Error('Walkthrough requires a browser with WebGL.');if(!bridge.getFloor().rooms.length)throw Error('Add a room before starting a walkthrough.');if(active){if(id)jump(id);return;}const room=bridge.getFloor().rooms.find(r=>r.id===id)||bridge.getFloor().rooms[0],spot=roomStation(bridge.getFloor(),room);if(!spot)throw Error('The room has no clear walking point.');position=spot;roomId=room.id;active=true;keys.clear();bridge.setView('3d');scene.controls.enabled=false;scene.editMode=false;scene.walkCamera=camera;scene.load(bridge.getFloor(),false);ceiling();hud.hidden=false;document.querySelector('.editor').classList.add('walking');updateCamera();last=performance.now();scene.walkUpdate=()=>{const now=performance.now(),dt=Math.min(.04,(now-last)/1000);last=now;let forward=Number(keys.has('w')||keys.has('arrowup'))-Number(keys.has('s')||keys.has('arrowdown')),side=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'));const speed=1.5*dt;if(forward||side){const L=Math.hypot(forward,side);move(forward/L*speed,side/L*speed);}if(keys.has('q')||keys.has('e')){yaw+=(Number(keys.has('q'))-Number(keys.has('e')))*dt;updateCamera();}};bridge.onWalkChange?.();}
 function stop(){if(!active)return;active=false;keys.clear();drag=null;scene.walkUpdate=null;scene.walkCamera=null;scene.controls.enabled=true;scene.editMode=true;hud.hidden=true;document.querySelector('.editor').classList.remove('walking');decorations?.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});decorations?.removeFromParent();decorations=null;bridge.render();bridge.onWalkChange?.();}
 if(scene){const load=scene.load.bind(scene);scene.load=(floor,cutaway)=>{const result=load(floor,active?false:cutaway);if(active)ceiling();return result;};oldDown=scene.down.bind(scene);scene.down=e=>{if(!active)oldDown(e);};
 scene.canvas.addEventListener('pointerdown',e=>{if(!active||e.button!==0)return;drag={x:e.clientX,y:e.clientY,yaw,pitch};scene.canvas.setPointerCapture(e.pointerId);});scene.canvas.addEventListener('pointermove',e=>{if(!active||!drag)return;yaw=drag.yaw-(e.clientX-drag.x)*.004;pitch=Math.max(-1.15,Math.min(1.15,drag.pitch-(e.clientY-drag.y)*.004));updateCamera();});for(const event of ['pointerup','pointercancel'])scene.canvas.addEventListener(event,()=>drag=null);
 }
 document.addEventListener('keydown',e=>{if(!active||document.querySelector('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const key=e.key.toLowerCase();if(key==='escape'){e.preventDefault();e.stopImmediatePropagation();stop();}else if(['w','a','s','d','q','e','arrowup','arrowdown','arrowleft','arrowright'].includes(key)){e.preventDefault();e.stopImmediatePropagation();keys.add(key);}},{capture:true});
 document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
 for(const b of document.querySelectorAll('[data-view],[data-tab],#model-studio-btn,#floor-select,#add-floor,#projects-btn')){b.addEventListener(b.id==='floor-select'?'change':'click',()=>stop(),{capture:true});}
 function state(){return{position:[...position],yaw,pitch,fov:camera.fov};}
 function restore(value){if(!active)start();position=[...value.position];yaw=value.yaw;pitch=value.pitch;camera.fov=value.fov;updateCamera();}
 function capture(wallId){if(!active)start();const renderer=scene.renderer,size=renderer.getSize(new THREE.Vector2()),ratio=renderer.getPixelRatio(),background=scene.scene.background,clip=renderer.clippingPlanes,shadow=renderer.shadowMap.enabled,tone=renderer.toneMapping,materials=[],hidden=[];
   try{renderer.setPixelRatio(1);renderer.setSize(1536,1024,false);camera.aspect=1.5;camera.updateProjectionMatrix();renderer.clippingPlanes=[];scene.scene.background=new THREE.Color('#f0ece5');
     for(const child of scene.scene.children)if(child!==scene.content&&child!==decorations&&!child.isLight){hidden.push([child,child.visible]);child.visible=false;}
     renderer.render(scene.scene,camera);const source=scene.canvas.toDataURL('image/png');let mask=null;
     if(wallId){scene.scene.background=new THREE.Color('white');renderer.shadowMap.enabled=false;renderer.toneMapping=THREE.NoToneMapping;const white=new THREE.MeshBasicMaterial({color:'white',side:THREE.DoubleSide}),black=new THREE.MeshBasicMaterial({color:'black',side:THREE.DoubleSide});
       scene.scene.traverse(o=>{if(!o.isMesh)return;let p=o,target=false;while(p){if(p.userData.kind==='wall'&&p.userData.id===wallId)target=true;p=p.parent;}materials.push([o,o.material]);o.material=target&&o.userData.wallSurface?black:white;});renderer.render(scene.scene,camera);
       const canvas=document.createElement('canvas');canvas.width=1536;canvas.height=1024;const ctx=canvas.getContext('2d');ctx.drawImage(scene.canvas,0,0);const pixels=ctx.getImageData(0,0,1536,1024);let count=0;for(let i=0;i<pixels.data.length;i+=4){const edit=pixels.data[i]<128;pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=255;pixels.data[i+3]=edit?0:255;if(edit)count++;}ctx.putImageData(pixels,0,0);mask=canvas.toDataURL('image/png');for(const [o,m]of materials)o.material=m;materials.length=0;white.dispose();black.dispose();if(count<40)throw Error('That wall is not visible. Look toward it before capturing.');
     }return {source,mask,camera:state(),roomId};
   }finally{for(const [o,m]of materials)o.material=m;for(const [o,v]of hidden)o.visible=v;renderer.shadowMap.enabled=shadow;renderer.toneMapping=tone;renderer.clippingPlanes=clip;scene.scene.background=background;renderer.setPixelRatio(ratio);renderer.setSize(size.x,size.y,false);updateCamera();renderer.render(scene.scene,camera);}
 }
 return {start,stop,jump,restore,capture,state,get active(){return active;},get roomId(){return roomId;}};
}
